import base64,hashlib,os,sys,socket
assert socket.gethostname()=='k8s-control01' and os.geteuid()==0,'STOP_HOST'
source=base64.b64decode('')
assert hashlib.sha256(source).hexdigest()=='ccdaaee72b0ce76027a9f2fd16ac37a9fe3dc5b76bd611d6cf0f74cae27abf37','STOP_SOURCE_HASH'
fd=os.memfd_create('oid02-reviewed-source',os.MFD_CLOEXEC)
try:
 with os.fdopen(os.dup(fd),'wb') as f:f.write(source)
 path='/proc/self/fd/'+str(fd)
 assert hashlib.sha256(open(path,'rb').read()).hexdigest()=='ccdaaee72b0ce76027a9f2fd16ac37a9fe3dc5b76bd611d6cf0f74cae27abf37'
 sys.argv=[path,'--source-commit','85939569b491aa4b89010a38f108cc8ab6c4ad18']
 exec(compile(source,path,'exec'),{'__name__':'__main__','__file__':path})
finally:os.close(fd)
